  "arguments": "{\"action\":\"read\",\"query\":\"update NODE_MODULE_VERSION to 134 ClangCL MSVC compile Windows\",\"snapshotId\":\"capture-dcf91794-dfd2-4d8a-b5a4-45d4abb7749e\"}",
