  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\",\"query\":\"ABI-stable changes to non-Node-API native code recompiled Node-API addons compiled against earlier version of Node.js\",\"segmentIndex\":3}",
