  "arguments": "{\"action\":\"read\",\"query\":\"ABI-stable changes to non-Node-API native code compiled against earlier version of Node.js recompilation required\",\"segmentIndex\":0,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
