  "arguments": "{\"action\":\"read\",\"query\":\"MSVC ClangCL required to compile Node.js on Windows V8 13.6 AsyncLocalStorage AsyncContextFrame\",\"segmentIndex\":0,\"snapshotId\":\"capture-dcf91794-dfd2-4d8a-b5a4-45d4abb7749e\"}",
