  "arguments": "{\"action\":\"read\",\"query\":\"use Node-API exclusively restricting itself to using node_api.h ensure ABI-compatible across Node.js major versions external libraries do not\",\"segmentIndex\":2,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
