  "arguments": "{\"action\":\"read\",\"query\":\"exclusively ABI-compatible add-on uses only its functions addon C++ wrapper node.h v8.h uv.h not stable\",\"segmentIndex\":0,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
