JavaScript environment so that the latter may be used with multiple implementations of Node-API. In the example below, addon.c and addon.h refer only to js_native_api.h. This ensures that addon.c can be reused to compile against either the Node.js implementation of Node-API or any implementation of Node-API outside of Node.js.\\n\\naddon_node.c is a separate file that contains the Node.js specific entry point to the addon and which instantiates the addon by calling into addon.c when the addon is loaded into a Node.js environment.\\n\\n// addon.h\\n#ifndef _ADDON_H_\\n#define _ADDON_H_\\n#include <js_native_api.h>\\nnapi_value create_addon(napi_env env);\\n#endif  // _ADDON_H_\\n\\nC\\nCOPY\\n// addon.c\\n#include \\\"addon.h\\\"\\n\\n#define NODE_API_CALL(env, call)                                  \\\\\\n  do {                                                            \\\\\\n    napi_status status = (call);                                  \\\\\\n    if (status != napi_ok) {                                      \\\\\\n      const napi_extended_error_info* error_info = NULL;          \\\\\\n      napi_get_last_error_info((env), &error_info);               \\\\\\n      const char* err_message = error_info->error_message;        \\\\\\n      bool is_pending;                                            \\\\\\n      napi_is_exception_pending((env), &is_pending);              \\\\\\n      /* If an exception is already pending, don't rethrow it */  \\\\\\n      if (!is_pending) {                                          \\\\\\n        const char* message = (err_message == NULL)               \\\\\\n            ? \\\"empty error message\\\"                               \\\\\\n            : err_message;                                        \\\\\\n        napi_throw_error((env), NULL, message);                   \\\\\\n      }                                                           \\\\\\n      return NULL;                                                \\\\\\n    }    