  "arguments": "{\"action\":\"read\",\"query\":\"ClangCL compile Node.js Windows MSVC removed toolchain\",\"segmentIndex\":0,\"snapshotId\":\"capture-dcf91794-dfd2-4d8a-b5a4-45d4abb7749e\"}",
