  "arguments": "{\"action\":\"read\",\"query\":\"node_api.h exclusively ABI-compatible addon restrict itself\",\"segmentIndex\":1,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
