  "arguments": "{\"action\":\"read\",\"query\":\"restricting itself include node_api.h use Node-API exclusively\",\"segmentIndex\":2,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
