  "arguments": "{\"action\":\"read\",\"query\":\"use Node-API exclusively ABI-compatible restrict itself node_api.h node.h uv.h\",\"segmentIndex\":0,\"snapshotId\":\"capture-542869a9-f12a-474b-be34-c133f83cb78a\"}",
